module robot_checker(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] instruction,\n    input wire [3:0] target_x,\n    input wire [3:0] target_y,\n    output reg result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] PARSE = 2'd1;\n    localparam [1:0] CHECK = 2'd2;\n    localparam [1:0] DONE = 2'd3;\n\n    reg [1:0] state;\n    reg [2:0] seg_count;\n    reg [3:0] segments [0:4];\n    reg [2:0] idx;\n\n    // Wires for computation\n    wire signed [4:0] x0_s, x2_s, x4_s, y1_s, y3_s;\n    wire signed [4:0] x_target_s, y_target_s;\n    wire signed [4:0] x_target_adj;\n    wire signed [4:0] x_cand [0:8];\n    wire signed [4:0] y_cand [0:8];\n    wire x_check, y_check;\n\n    // Parse logic (combinational)\n    integer i;\n    always @(*) begin\n        segments[0] = 4'd0;\n        segments[1] = 4'd0;\n        segments[2] = 4'd0;\n        segments[3] = 4'd0;\n        segments[4] = 4'd0;\n        seg_count = 3'd0;\n        idx = 3'd0;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (instruction[i]) begin\n                idx = idx + 1;\n            end else begin\n                if (seg_count < 5) begin\n                    segments[seg_count] = idx;\n                    seg_count = seg_count + 1;\n                end\n                idx = 3'd0;\n            end\n        end\n        if (seg_count < 5) begin\n            segments[seg_count] = idx;\n        end\n    end\n\n    // Assign segments to axes\n    assign x0_s = $signed({1'b0, segments[0]});\n    assign x2_s = $signed({1'b0, segments[2]});\n    assign x4_s = $signed({1'b0, segments[4]});\n    assign y1_s = $signed({1'b0, segments[1]});\n    assign y3_s = $signed({1'b0, segments[3]});\n\n    // Target assignments\n    assign x_target_s = $signed(target_x);\n    assign y_target_s = $signed(target_y);\n    assign x_target_adj = x_target_s - x0_s;\n\n    // Generate candidate sets\n    assign x_cand[0] = 5'sd0;\n    assign x_cand[1] = x2_s;\n    assign x_cand[2] = -x2_s;\n    assign x_cand[3] = x4_s;\n    assign x_cand[4] = -x4_s;\n    assign x_cand[5] = x2_s + x4_s;\n    assign x_cand[6] = x2_s - x4_s;\n    assign x_cand[7] = -x2_s + x4_s;\n    assign x_cand[8] = -x2_s - x4_s;\n\n    assign y_cand[0] = 5'sd0;\n    assign y_cand[1] = y1_s;\n    assign y_cand[2] = -y1_s;\n    assign y_cand[3] = y3_s;\n    assign y_cand[4] = -y3_s;\n    assign y_cand[5] = y1_s + y3_s;\n    assign y_cand[6] = y1_s - y3_s;\n    assign y_cand[7] = -y1_s + y3_s;\n    assign y_cand[8] = -y1_s - y3_s;\n\n    // Check functions\n    assign x_check = (x_target_adj == x_cand[0]) || (x_target_adj == x_cand[1]) ||\n                     (x_target_adj == x_cand[2]) || (x_target_adj == x_cand[3]) ||\n                     (x_target_adj == x_cand[4]) || (x_target_adj == x_cand[5]) ||\n                     (x_target_adj == x_cand[6]) || (x_target_adj == x_cand[7]) ||\n                     (x_target_adj == x_cand[8]);\n\n    assign y_check = (y_target_s == y_cand[0]) || (y_target_s == y_cand[1]) ||\n                     (y_target_s == y_cand[2]) || (y_target_s == y_cand[3]) ||\n                     (y_target_s == y_cand[4]) || (y_target_s == y_cand[5]) ||\n                     (y_target_s == y_cand[6]) || (y_target_s == y_cand[7]) ||\n                     (y_target_s == y_cand[8]);\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            idx <= 3'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= PARSE;\n                end\n                PARSE: begin\n                    state <= CHECK;\n                end\n                CHECK: begin\n                    result <= x_check && y_check;\n                    state <= DONE;\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule